SELECT id, tenant_id, name, description, embed_model, chunk_config,
       status, doc_count, created_by, created_at, updated_at
FROM kb_knowledge_base
WHERE tenant_id = #{tenantId}
  AND name = #{name}
LIMIT 1

SELECT id, tenant_id, name, description, embed_model, chunk_config,
       status, doc_count, created_by, created_at, updated_at
FROM kb_knowledge_base
WHERE tenant_id = #{tenantId}
  AND status = #{status}
ORDER BY created_at DESC
